CREATE VIEW VW_ISTANZE_OPE_RUOLI (IDCOMUNE, IDRUOLO, CODICERESPONSABILE, CODICEISTANZA) AS SELECT RR.IDCOMUNE,RR.IDRUOLO,RR.CODICERESPONSABILE,IR.CODICEISTANZA FROM RESPONSABILIRUOLI RR INNER JOIN ISTANZERUOLI IR on rr.idcomune =ir.idcomune and rr.idruolo = ir.idruolo inner join ruoli r ON r.idcomune=ir.idcomune and r.id =ir.idruolo AND (r.readonly=0 OR (r.flag_gestmovimenti=1 OR r.flag_disgestmovamm =1))
