CREATE VIEW VW_I_ATTIVITAINFORMAZIONI AS SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZEATTIVITA.CODICEISTANZA, ISTANZEATTIVITA.CODICEATTIVITA, ISTANZEATTIVITA.METRIQ, ISTANZEATTIVITA.NOTE, ISTANZEATTIVITA.IDCOMUNE, ISTANZEATTIVITA.SOFTWARE, ISTANZEATTIVITA.IDATTIVITA, SETTORI.CODICESETTORE, SETTORI.SETTORE FROM I_ATTIVITA, ISTANZEATTIVITA, ATTIVITA, SETTORI WHERE SETTORI.IDCOMUNE = ATTIVITA.IDCOMUNE AND SETTORI.CODICESETTORE = ATTIVITA.CODICESETTORE AND ATTIVITA.IDCOMUNE = ISTANZEATTIVITA.IDCOMUNE AND ATTIVITA.CODICEISTAT = ISTANZEATTIVITA.CODICEATTIVITA AND ISTANZEATTIVITA.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZEATTIVITA.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA
