CREATE  VIEW VW_I_ATTIVITAENDO as SELECT I_ATTIVITA.IDCOMUNE, I_ATTIVITA.ID AS I_IDATTIVITA, ISTANZEPROCEDIMENTI.CODICEISTANZA, TIPIFAMIGLIEENDO.CODICE AS CODICEFAMIGLIA, TIPIFAMIGLIEENDO.TIPO AS FAMIGLIA, TIPIENDO.CODICE AS CODICETIPO, TIPIENDO.TIPO, ISTANZEPROCEDIMENTI.CODICEINVENTARIO, INVENTARIOPROCEDIMENTI.PROCEDIMENTO, ISTANZEPROCEDIMENTI.PERPROVVEDIMENTO, ISTANZEPROCEDIMENTI.ACQUISITO, ISTANZEPROCEDIMENTI.DATAATTIVAZIONE, ISTANZEPROCEDIMENTI.NOTE FROM I_ATTIVITA, ISTANZE, ISTANZEPROCEDIMENTI, ((INVENTARIOPROCEDIMENTI LEFT OUTER JOIN TIPIENDO ON INVENTARIOPROCEDIMENTI.IDCOMUNE = TIPIENDO.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICETIPO = TIPIENDO.CODICE ) LEFT OUTER JOIN TIPIFAMIGLIEENDO ON TIPIENDO.IDCOMUNE = TIPIFAMIGLIEENDO.IDCOMUNE AND TIPIENDO.CODICEFAMIGLIAENDO = TIPIFAMIGLIEENDO.CODICE ) WHERE INVENTARIOPROCEDIMENTI.IDCOMUNE = ISTANZEPROCEDIMENTI.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = ISTANZEPROCEDIMENTI.CODICEINVENTARIO AND ISTANZEPROCEDIMENTI.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZEPROCEDIMENTI.CODICEISTANZA = ISTANZE.CODICEISTANZA AND ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID  WITH CHECK OPTION
GO
COMMIT
