CREATE VIEW VW_LISTAAUTORIZZAZIONI AS SELECT AUTORIZZAZIONI.IDCOMUNE, AUTORIZZAZIONI.FKIDISTANZA AS CODICEISTANZA,ISTANZE.NUMEROISTANZA,AUTORIZZAZIONI.AUTORIZNUMERO AS NUMEROAUTORIZZAZIONE,AUTORIZZAZIONI.AUTORIZDATA AS DATAAUTORIZZAZIONE,COMUNI.COMUNE AS COMUNEAUTORIZZAZIONE, TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS REGISTRO, ANAGRAFE.CODICEANAGRAFE,  (ANAGRAFE.NOMINATIVO + ' ' + ANAGRAFE.NOME)  AS ANAGRAFICA, ISTANZE.LAVORI  AS OGGETTOISTANZA, STRADARIO.CODICESTRADARIO AS LOCALIZZAZIONECODICEVIA, (STRADARIO.PREFISSO+ ' '+ STRADARIO.DESCRIZIONE) AS LOCALIZZAZIONE, ISTANZESTRADARIO.CIVICO  AS LOCALIZZAZIONECIVICO FROM AUTORIZZAZIONI LEFT JOIN ISTANZE ON AUTORIZZAZIONI.IDCOMUNE  =ISTANZE.IDCOMUNE AND AUTORIZZAZIONI.FKIDISTANZA=ISTANZE.CODICEISTANZA LEFT JOIN ISTANZESTRADARIO ON ISTANZESTRADARIO.IDCOMUNE  =ISTANZE.IDCOMUNE AND ISTANZESTRADARIO.CODICEISTANZA=ISTANZE.CODICEISTANZA LEFT JOIN STRADARIO ON ISTANZESTRADARIO.IDCOMUNE  =STRADARIO.IDCOMUNE AND ISTANZESTRADARIO.CODICESTRADARIO=STRADARIO.CODICESTRADARIO LEFT JOIN TIPOLOGIAREGISTRI ON TIPOLOGIAREGISTRI.IDCOMUNE=AUTORIZZAZIONI.IDCOMUNE AND TIPOLOGIAREGISTRI.TR_ID  =AUTORIZZAZIONI.FKIDREGISTRO, ANAGRAFE, COMUNI WHERE ANAGRAFE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND ANAGRAFE.CODICEANAGRAFE = AUTORIZZAZIONI.FK_CODICEANAGRAFE AND COMUNI.CODICECOMUNE =AUTORIZZAZIONI.AUTORIZCOMUNE AND (ISTANZESTRADARIO.PRIMARIO=1 OR ISTANZESTRADARIO.PRIMARIO IS NULL)
GO
COMMIT
GO